for r in lines[6:]:
    for cell in r[:5]:
        if cell in targets:
            non_empty = {f"{i}:{h5[i] if i<len(h5) else ''}": v for i, v in enumerate(r) if v != ''}
            print(cell, json.dumps(non_empty, ensure_ascii=False))

# 2. Check Amazon Bulk order 2023 & 2024 + 周订单总表 2023 & 2024
